package com.coffeeshop.model;import java.time.LocalDateTime;public final class NotificationModels{private NotificationModels(){}public record Notification(long id,String type,String title,String message,String entityType,Long entityId,boolean read,LocalDateTime readAt,LocalDateTime expiresAt,LocalDateTime createdAt,byte[]version){public Notification{version=version.clone();}@Override public byte[]version(){return version.clone();}public boolean expired(LocalDateTime now){return expiresAt!=null&&!expiresAt.isAfter(now);}}}
